import SwiftUI

/// States supported by the original thinking-orbs component.
public enum ThinkingOrbState: String, CaseIterable, Sendable {
    case working
    case searching
    case solving
    case listening
    case connecting
    case weaving
    case composing
    case breathing
    case shaping
}

/// Faithful SwiftUI port of the thinking-orbs (Libraries.dev) component.
///
/// Implements the exact geometry, colors, timing, and size tunings (64 and 20)
/// of thinking-orbs 0.3.2, with clean proportional scaling for larger displays.
public struct ThinkingOrb: View {
    public var state: ThinkingOrbState = .breathing
    public var size: CGFloat = 64
    public var speed: Double = 1.0
    public var dotSize: Double = 1.0
    public var dark: Bool = true
    public var paused: Bool = false

    @Environment(\.accessibilityReduceMotion) private var systemReduceMotion

    public init(
        state: ThinkingOrbState = .breathing,
        size: CGFloat = 64,
        speed: Double = 1.0,
        dotSize: Double = 1.0,
        dark: Bool = true,
        paused: Bool = false
    ) {
        self.state = state
        self.size = size
        self.speed = speed
        self.dotSize = dotSize
        self.dark = dark
        self.paused = paused
    }

    public var body: some View {
        let isStatic = paused || systemReduceMotion
        TimelineView(.animation(paused: isStatic)) { timeline in
            let baseSize: CGFloat = size <= 28 ? 20 : 64
            let scaleFactor = size / baseSize
            let preset = ThinkingOrbEngine.preset(for: state, baseSize: baseSize)
            let effSpeed = preset.baseSpeed * speed
            let tSec: Double = isStatic ? 0.6 : (timeline.date.timeIntervalSinceReferenceDate * effSpeed)
            let frame = ThinkingOrbEngine.computeFrame(
                baseSize: baseSize,
                t: tSec,
                preset: preset,
                dotSizeMultiplier: dotSize
            )

            Canvas { context, _ in
                context.scaleBy(x: scaleFactor, y: scaleFactor)
                for dot in frame.dots {
                    let w = min(1.0, max(0.0, dot.white))
                    let g = dark ? (1.0 - w) : w
                    let color = Color(red: g, green: g, blue: g).opacity(dot.a)
                    let rect = CGRect(
                        x: dot.x - dot.r,
                        y: dot.y - dot.r,
                        width: dot.r * 2,
                        height: dot.r * 2
                    )
                    context.fill(Path(ellipseIn: rect), with: .color(color))
                }
            }
            .frame(width: size, height: size)
        }
        .accessibilityElement()
        .accessibilityLabel(Text(state.rawValue.capitalized))
    }
}

// MARK: - Core Math Engine (exact thinking-orbs 0.3.2 breathing / ring algorithm)

struct ThinkingOrbEngine {
    struct Dot: Sendable {
        var x: Double
        var y: Double
        var z: Double
        var r: Double
        var white: Double
        var a: Double
    }

    struct Frame: Sendable {
        var dots: [Dot]
    }

    struct PresetConfig: Sendable {
        let baseSpeed: Double
        let lanes: Int
        let segs: Int
        let rBase: Double
        let rDepth: Double
        let rsPow: Double
        let rMin: Double
        let spin: Double
        let bandMul: Double
        let wobMul: Double
        let faceOn: Double
    }

    /// Presets matching `resolvePreset("breathing", 64)` and `resolvePreset("breathing", 20)` in thinking-orbs 0.3.2.
    static func preset(for state: ThinkingOrbState, baseSize: CGFloat) -> PresetConfig {
        if baseSize <= 28 {
            // Size 20 tuning from PRESETS.ring[20]
            return PresetConfig(
                baseSpeed: 3.78,
                lanes: 2,
                segs: 15,
                rBase: 1.7842,
                rDepth: 2.7574,
                rsPow: 0.6,
                rMin: 0.3,
                spin: 0.0,
                bandMul: 3.968,
                wobMul: 0.565,
                faceOn: 1.0
            )
        } else {
            // Size 64 tuning from PRESETS.ring[64]
            return PresetConfig(
                baseSpeed: 3.24,
                lanes: 3,
                segs: 44,
                rBase: 1.0516,
                rDepth: 1.6252,
                rsPow: 0.6,
                rMin: 0.3,
                spin: 0.0,
                bandMul: 3.627,
                wobMul: 0.368,
                faceOn: 1.0
            )
        }
    }

    static func radiusScale(size: Double, pow: Double) -> Double {
        Foundation.pow(size / 300.0, pow)
    }

    static func project(
        x: Double,
        y: Double,
        z: Double,
        yaw: Double,
        tilt: Double,
        cx: Double,
        cy: Double,
        scale: Double
    ) -> (x: Double, y: Double, z: Double) {
        let st = sin(tilt)
        let ct = cos(tilt)
        let sy = sin(yaw)
        let cyw = cos(yaw)

        let x1 = x * cyw + z * sy
        let z1 = -x * sy + z * cyw
        let y1 = y * ct - z1 * st
        let z2 = y * st + z1 * ct
        return (cx + x1 * scale, cy - y1 * scale, z2)
    }

    static func computeFrame(
        baseSize: CGFloat,
        t: Double,
        preset: PresetConfig,
        dotSizeMultiplier: Double
    ) -> Frame {
        let size = Double(baseSize)
        let cx = size / 2.0
        let cy = size / 2.0
        let R = (size / 2.0) * 0.78
        let camTilt = 0.3
        let rs = radiusScale(size: size, pow: preset.rsPow)

        let effRBase = preset.rBase * dotSizeMultiplier
        let effRDepth = preset.rDepth * dotSizeMultiplier

        let ya = t * 0.24 * preset.spin
        let ta = preset.faceOn > 0 ? -camTilt : (0.55 + 0.3 * sin(t * 0.18) * preset.spin)
        let ux = cos(ya)
        let uy = 0.0
        let uz = sin(ya)
        let vx = -uz * sin(ta)
        let vy = cos(ta)
        let vz = ux * sin(ta)
        let nx = uy * vz - uz * vy
        let ny = uz * vx - ux * vz
        let nz = ux * vy - uy * vx

        let wobAmp = 0.23 * preset.wobMul
        let baseR = preset.faceOn > 0 ? (R / (1.0 + 0.85 * wobAmp)) : R
        let lanes = max(1, Int(round(Double(preset.lanes) * preset.bandMul)))
        let segs = preset.segs

        var dots: [Dot] = []
        dots.reserveCapacity(lanes * segs)

        let halfLanes = Double(lanes - 1) / 2.0
        let maxEdge = max(1.0, halfLanes)

        for w in 0..<lanes {
            let laneOff = (Double(w) - halfLanes) * 0.075
            let edge = abs(Double(w) - halfLanes) / maxEdge
            for k in 0..<segs {
                let a = (Double(k) / Double(segs)) * 2.0 * .pi
                let wob = (0.16 * sin(a * 3.0 - t * 1.7 + Double(w) * 0.22) +
                           0.07 * sin(a * 5.0 + t * 1.1)) * preset.wobMul
                let radial = preset.faceOn > 0 ? (1.0 + wob) : 1.0
                let off = preset.faceOn > 0 ? laneOff : (laneOff + wob)

                let x = ux * cos(a) + vx * sin(a) + nx * off
                let y = uy * cos(a) + vy * sin(a) + ny * off
                let z = uz * cos(a) + vz * sin(a) + nz * off
                let len = sqrt(x * x + y * y + z * z)
                let rr = baseR * radial

                let p = project(
                    x: (x / len) * rr,
                    y: (y / len) * rr,
                    z: (z / len) * rr,
                    yaw: t * 0.1 * preset.spin,
                    tilt: camTilt,
                    cx: cx,
                    cy: cy,
                    scale: 1.0
                )

                let depth = (p.z / R + 1.0) / 2.0
                let dotAlpha = 0.4 + 0.6 * depth
                if dotAlpha >= 0.02 {
                    let dotR = max(preset.rMin, (effRBase + effRDepth * depth) * (1.0 - 0.25 * edge) * rs)
                    let white = 0.52 - 0.44 * depth + 0.18 * edge
                    dots.append(Dot(x: p.x, y: p.y, z: p.z, r: dotR, white: white, a: dotAlpha))
                }
            }
        }

        dots.sort { $0.z < $1.z }
        return Frame(dots: dots)
    }
}
