import SwiftUI

/// App states defined by the Orbs brand kit.
public enum OrbsAppState: String, CaseIterable, Sendable {
    case idle
    case listening
    case thinking
    case acting
    case confirmation
    case done
    case error

    /// Converts from BeaverAgent app `OrbState`.
    init(orbState: OrbState) {
        switch orbState {
        case .idle: self = .idle
        case .listening: self = .listening
        case .thinking: self = .thinking
        case .searching: self = .acting
        case .speaking: self = .acting
        case .confirmation: self = .confirmation
        case .done: self = .done
        case .error: self = .error
        }
    }
}

/// SwiftUI implementation of `OrbsIndicator` from `docs/brand-kit/OrbsIndicator.tsx`.
///
/// Wraps `ThinkingOrb(state: .breathing)` with per-state speed/dotSize presets
/// and the brand kit's wrapper motion curves (irregular pulse, continuous rotation, three-burst action).
public struct OrbsIndicator: View {
    public var state: OrbsAppState
    public var size: CGFloat = 64
    public var dark: Bool = true
    public var reducedMotion: Bool = false

    @Environment(\.accessibilityReduceMotion) private var systemReduceMotion

    public init(
        state: OrbsAppState,
        size: CGFloat = 64,
        dark: Bool = true,
        reducedMotion: Bool = false
    ) {
        self.state = state
        self.size = size
        self.dark = dark
        self.reducedMotion = reducedMotion
    }

    init(
        orbState: OrbState,
        size: CGFloat = 64,
        dark: Bool = true,
        reducedMotion: Bool = false
    ) {
        self.init(state: OrbsAppState(orbState: orbState), size: size, dark: dark, reducedMotion: reducedMotion)
    }

    private var isEffectivelyPaused: Bool {
        reducedMotion || systemReduceMotion || state == .confirmation || state == .done || state == .error
    }

    private var preset: (speed: Double, dotSize: Double) {
        switch state {
        case .idle: (speed: 0.3, dotSize: 0.8)
        case .listening: (speed: 0.65, dotSize: 1.0)
        case .thinking: (speed: 0.75, dotSize: 1.0)
        case .acting: (speed: 1.2, dotSize: 1.15)
        case .confirmation, .done, .error: (speed: 0.3, dotSize: 0.8)
        }
    }

    public var body: some View {
        TimelineView(.animation(paused: isEffectivelyPaused)) { timeline in
            let t = isEffectivelyPaused ? 0.0 : timeline.date.timeIntervalSinceReferenceDate
            let motion = OrbsMotionEngine.transform(for: state, at: t, isPaused: isEffectivelyPaused)

            ThinkingOrb(
                state: .breathing,
                size: size,
                speed: preset.speed,
                dotSize: preset.dotSize,
                dark: dark,
                paused: isEffectivelyPaused
            )
            .scaleEffect(motion.scale)
            .rotationEffect(.degrees(motion.rotation))
            .frame(width: size, height: size)
        }
        .accessibilityElement()
        .accessibilityLabel(Text(state.rawValue.capitalized))
    }
}

// MARK: - Motion Engine (exact orb-motion.css transforms)

struct OrbsMotionEngine {
    struct Transform: Sendable {
        var scale: CGFloat
        var rotation: Double
    }

    struct UnitBezier: Sendable {
        let p1x: Double
        let p1y: Double
        let p2x: Double
        let p2y: Double

        func solve(x: Double) -> Double {
            if x <= 0 { return 0 }
            if x >= 1 { return 1 }
            var s = x
            for _ in 0..<8 {
                let dx = sampleX(s) - x
                if abs(dx) < 1e-6 { break }
                let d = sampleDx(s)
                if abs(d) < 1e-6 { break }
                s -= dx / d
            }
            return sampleY(max(0, min(1, s)))
        }

        private func sampleX(_ t: Double) -> Double {
            3 * (1 - t) * (1 - t) * t * p1x + 3 * (1 - t) * t * t * p2x + t * t * t
        }

        private func sampleY(_ t: Double) -> Double {
            3 * (1 - t) * (1 - t) * t * p1y + 3 * (1 - t) * t * t * p2y + t * t * t
        }

        private func sampleDx(_ t: Double) -> Double {
            3 * (1 - t) * (1 - t) * p1x + 6 * (1 - t) * t * (p2x - p1x) + 3 * t * t * (1 - p2x)
        }
    }

    static let easeInOut = UnitBezier(p1x: 0.42, p1y: 0.0, p2x: 0.58, p2y: 1.0)
    static let actBezier = UnitBezier(p1x: 0.2, p1y: 0.7, p2x: 0.2, p2y: 1.0)

    static let listenKeyframes: [(p: Double, scale: Double)] = [
        (0.00, 0.90),
        (0.16, 1.16),
        (0.32, 0.94),
        (0.47, 1.08),
        (0.61, 0.88),
        (0.78, 1.20),
        (0.90, 0.97),
        (1.00, 0.90)
    ]

    static let actKeyframes: [(p: Double, rot: Double, scale: Double)] = [
        (0.00, 0.0, 1.0),
        (0.22, 120.0, 1.12),
        (0.34, 120.0, 1.0),
        (0.56, 240.0, 1.12),
        (0.68, 240.0, 1.0),
        (0.90, 360.0, 1.12),
        (1.00, 360.0, 1.0)
    ]

    static func transform(for state: OrbsAppState, at t: Double, isPaused: Bool) -> Transform {
        if isPaused {
            return Transform(scale: 1.0, rotation: 0.0)
        }

        switch state {
        case .idle, .confirmation, .done, .error:
            return Transform(scale: 1.0, rotation: 0.0)

        case .listening:
            // animation: orbs-listen 2.6s ease-in-out infinite
            let duration = 2.6
            let rawProgress = (t / duration).truncatingRemainder(dividingBy: 1.0)
            let progress = rawProgress < 0 ? (rawProgress + 1.0) : rawProgress

            for i in 0..<(listenKeyframes.count - 1) {
                let k0 = listenKeyframes[i]
                let k1 = listenKeyframes[i + 1]
                if progress >= k0.p && progress <= k1.p {
                    let segmentSpan = k1.p - k0.p
                    let segmentProgress = segmentSpan > 0 ? ((progress - k0.p) / segmentSpan) : 0
                    let eased = easeInOut.solve(x: segmentProgress)
                    let scale = k0.scale + (k1.scale - k0.scale) * eased
                    return Transform(scale: CGFloat(scale), rotation: 0.0)
                }
            }
            return Transform(scale: 0.90, rotation: 0.0)

        case .thinking:
            // animation: orbs-think 4.5s linear infinite
            let duration = 4.5
            let rawProgress = (t / duration).truncatingRemainder(dividingBy: 1.0)
            let progress = rawProgress < 0 ? (rawProgress + 1.0) : rawProgress
            return Transform(scale: 1.0, rotation: progress * 360.0)

        case .acting:
            // animation: orbs-act 2.2s cubic-bezier(.2,.7,.2,1) infinite
            let duration = 2.2
            let rawProgress = (t / duration).truncatingRemainder(dividingBy: 1.0)
            let progress = rawProgress < 0 ? (rawProgress + 1.0) : rawProgress

            for i in 0..<(actKeyframes.count - 1) {
                let k0 = actKeyframes[i]
                let k1 = actKeyframes[i + 1]
                if progress >= k0.p && progress <= k1.p {
                    let segmentSpan = k1.p - k0.p
                    let segmentProgress = segmentSpan > 0 ? ((progress - k0.p) / segmentSpan) : 0
                    let eased = actBezier.solve(x: segmentProgress)
                    let rot = k0.rot + (k1.rot - k0.rot) * eased
                    let scale = k0.scale + (k1.scale - k0.scale) * eased
                    return Transform(scale: CGFloat(scale), rotation: rot)
                }
            }
            return Transform(scale: 1.0, rotation: 0.0)
        }
    }
}

