//
//  ThinkingOrb.swift
//  BeaverAgent
//
//  SwiftUI port of the `breathing` state of thinking-orbs 0.3.2
//  (https://github.com/Jakubantalik/Libraries.dev, https://libraries.dev/orbs.html).
//  MIT License, Copyright (c) 2026 Jakub Antalik. See frontend/THIRD_PARTY_NOTICES.md.
//
//  Ported line by line from dist/index-B8WsUNf5.js: BASE_PROFILES.ring, PRESETS.ring,
//  resolvePreset, scaleCounts, scaleRadii, frameRibbon (faceOn), finalizeFrame and paint.
//  The brand kit (docs/brand-kit) uses only the breathing geometry, so the other eight
//  library states are not ported.
//

import SwiftUI

/// The library states this port draws. The brand kit uses `breathing` for every app state.
enum ThinkingOrbState: String {
    case breathing
}

/// A dotted, face-on ring that slowly morphs: thinking-orbs `<ThinkingOrb state="breathing" />`.
///
/// `size` picks the library's hand-tuned 20 or 64 design (whichever is closer) and scales it
/// to the requested points, so a 104 pt hero orb is the 64 design drawn larger.
struct ThinkingOrb: View {
    var state: ThinkingOrbState = .breathing
    var size: CGFloat = 64
    /// Multiplies the preset's animation clock.
    var speed: Double = 1
    /// Multiplies every dot radius, as the library's `dotSize` prop.
    var dotSize: Double = 1
    /// Light ink for dark backgrounds, dark ink for light ones.
    var dark: Bool = false
    /// Freezes the animation on the current frame.
    var paused: Bool = false

    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        let tuning: CGFloat = size < 36 ? 20 : 64
        let preset = RingPreset.resolve(tuning: Int(tuning), dotSize: dotSize)
        let effSpeed = preset.speed * speed
        TimelineView(.animation(paused: paused || reduceMotion)) { timeline in
            // The library draws frame(0.6) under reduced motion, else performance.now() * speed.
            let t = reduceMotion ? 0.6 : timeline.date.timeIntervalSince(ThinkingOrb.clockStart) * effSpeed
            Canvas { context, _ in
                context.scaleBy(x: size / tuning, y: size / tuning)
                for dot in RingPreset.frame(size: Double(tuning), t: t, opts: preset.opts) {
                    let w = min(1, max(0, dot.white))
                    let g = ((dark ? 1 - w : w) * 255).rounded() / 255
                    let rect = CGRect(x: dot.x - dot.r, y: dot.y - dot.r, width: dot.r * 2, height: dot.r * 2)
                    context.fill(Path(ellipseIn: rect), with: .color(Color(white: g, opacity: dot.a)))
                }
            }
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }

    /// The library's clock is `performance.now()`, which counts from page load.
    private static let clockStart = Date()
}

// MARK: - Engine

/// `BASE_PROFILES.ring` resolved through `PRESETS.ring`, plus `frameRibbon` with `faceOn`.
enum RingPreset {
    struct Opts {
        var lanes: Int
        var segs: Int
        var rBase: Double
        var rDepth: Double
        var rsPow = 0.6
        var rMin = 0.3
        var spin: Double
        var bandMul: Double
        var wobMul: Double
    }

    struct Dot {
        var x, y, z, r, white, a: Double
    }

    /// `resolvePreset("breathing", tuning)` followed by the `dotSize` radius scale.
    static func resolve(tuning: Int, dotSize: Double) -> (speed: Double, opts: Opts) {
        // PRESETS.ring[64] and PRESETS.ring[20]
        let p: (speed: Double, count: Double, size: Double, bandMul: Double, wobMul: Double) =
            tuning == 20
            ? (3.78, 0.028, 1.622, 3.968, 0.565)
            : (3.24, 0.25, 0.956, 3.627, 0.368)
        // scaleCounts pairs lanes with segs and scales both by sqrt(count).
        let rt = p.count.squareRoot()
        let radius = p.size * max(0.1, dotSize)
        let opts = Opts(
            lanes: max(2, Int((5 * rt).rounded())),
            segs: max(2, Int((88 * rt).rounded())),
            rBase: 1.1 * radius,
            rDepth: 1.7 * radius,
            spin: 0,
            bandMul: p.bandMul,
            wobMul: p.wobMul
        )
        return (p.speed, opts)
    }

    /// `frameRibbon(size, t, opts)` for the ring profile (`faceOn: 1`, `ghostN: 0`),
    /// already finalized: faint dots dropped, radii clamped, sorted back to front.
    static func frame(size: Double, t: Double, opts o: Opts) -> [Dot] {
        let cx = size / 2
        let cy = size / 2
        let R = size / 2 * 0.78
        let camTilt = 0.3
        let rs = pow(size / 300, o.rsPow)

        let ya = t * 0.24 * o.spin
        let ta = -camTilt
        let ux = cos(ya), uy = 0.0, uz = sin(ya)
        let vx = -uz * sin(ta), vy = cos(ta), vz = ux * sin(ta)
        let nx = uy * vz - uz * vy
        let ny = uz * vx - ux * vz
        let nz = ux * vy - uy * vx

        let wobAmp = 0.23 * o.wobMul
        let baseR = R / (1 + 0.85 * wobAmp)
        let lanes = max(1, Int((Double(o.lanes) * o.bandMul).rounded()))
        let segs = o.segs
        let half = Double(lanes - 1) / 2

        // makeProj(t * 0.1 * spin, camTilt, cx, cy, 1)
        let yaw = t * 0.1 * o.spin
        let st = sin(camTilt), ct = cos(camTilt), sy = sin(yaw), cyw = cos(yaw)

        var dots: [Dot] = []
        dots.reserveCapacity(lanes * segs)
        for w in 0..<lanes {
            let laneOff = (Double(w) - half) * 0.075
            let edge = abs(Double(w) - half) / max(1, half)
            for k in 0..<segs {
                let a = Double(k) / Double(segs) * 2 * .pi
                let wob = (0.16 * sin(a * 3 - t * 1.7 + Double(w) * 0.22) + 0.07 * sin(a * 5 + t * 1.1)) * o.wobMul
                let radial = 1 + wob
                let x = ux * cos(a) + vx * sin(a) + nx * laneOff
                let y = uy * cos(a) + vy * sin(a) + ny * laneOff
                let z = uz * cos(a) + vz * sin(a) + nz * laneOff
                let l = (x * x + y * y + z * z).squareRoot()
                let rr = baseR * radial
                let (px, py, pz) = (x / l * rr, y / l * rr, z / l * rr)

                let x1 = px * cyw + pz * sy
                let z1 = -px * sy + pz * cyw
                let y1 = py * ct - z1 * st
                let z2 = py * st + z1 * ct

                let depth = (z2 / R + 1) / 2
                let alpha = 0.4 + 0.6 * depth
                guard alpha >= 0.02 else { continue }
                dots.append(Dot(
                    x: cx + x1,
                    y: cy - y1,
                    z: z2,
                    r: max(o.rMin, (o.rBase + o.rDepth * depth) * (1 - 0.25 * edge) * rs),
                    white: 0.52 - 0.44 * depth + 0.18 * edge,
                    a: alpha
                ))
            }
        }
        dots.sort { $0.z < $1.z }
        return dots
    }
}

//
//  OrbsIndicator.swift
//  BeaverAgent
//
//  SwiftUI port of docs/brand-kit/OrbsIndicator.tsx and orb-motion.css (Orbs brand kit v1.0,
//  Ring direction). Every state draws the thinking-orbs `breathing` geometry (ThinkingOrb.swift);
//  a wrapper adds each state's own motion.
//

import SwiftUI

/// App states of the brand kit's state contract.
enum OrbsAppState: String, CaseIterable {
    case idle, listening, thinking, acting, confirmation, done, error

    init(_ state: OrbState) {
        switch state {
        case .idle: self = .idle
        case .listening: self = .listening
        case .thinking: self = .thinking
        case .searching, .speaking: self = .acting
        }
    }

    /// `presets` in OrbsIndicator.tsx.
    var preset: (speed: Double, dotSize: Double) {
        switch self {
        case .idle, .confirmation, .done, .error: (0.3, 0.8)
        case .listening: (0.65, 1)
        case .thinking: (0.75, 1)
        case .acting: (1.2, 1.15)
        }
    }

    /// Confirmation, done and error hold still; their label and icon carry the state.
    var isStatic: Bool {
        self == .confirmation || self == .done || self == .error
    }
}

/// `<OrbsIndicator state size dark reducedMotion />`: the breathing orb with the state's preset
/// and wrapper motion. Decorative; show the state as visible text beside it.
struct OrbsIndicator: View {
    var state: OrbsAppState
    var size: CGFloat = 64
    var dark = false
    var reducedMotion = false

    @Environment(\.accessibilityReduceMotion) private var systemReduceMotion
    /// CSS restarts the keyframes whenever `data-motion` changes.
    @State private var motionStart = Date()

    var body: some View {
        let paused = reducedMotion || state.isStatic
        let still = paused || systemReduceMotion
        TimelineView(.animation(paused: still)) { timeline in
            let motion = still
                ? OrbsMotion.rest
                : OrbsMotion.transform(state, at: timeline.date.timeIntervalSince(motionStart))
            ThinkingOrb(
                state: .breathing,
                size: size,
                speed: state.preset.speed,
                dotSize: state.preset.dotSize,
                dark: dark,
                paused: paused
            )
            .rotationEffect(.degrees(motion.rotation))
            .scaleEffect(motion.scale)
        }
        .frame(width: size, height: size)
        .onChange(of: state) { motionStart = Date() }
        .accessibilityHidden(true)
    }
}

// MARK: - orb-motion.css

enum OrbsMotion {
    struct Transform {
        var scale: Double
        var rotation: Double
    }

    struct Keyframe {
        var at: Double
        var scale: Double
        var rotation: Double = 0
    }

    static let rest = Transform(scale: 1, rotation: 0)

    /// `orbs-listen 2.6s ease-in-out infinite`
    static let listen: [Keyframe] = [
        .init(at: 0, scale: 0.9), .init(at: 0.16, scale: 1.16), .init(at: 0.32, scale: 0.94),
        .init(at: 0.47, scale: 1.08), .init(at: 0.61, scale: 0.88), .init(at: 0.78, scale: 1.2),
        .init(at: 0.9, scale: 0.97), .init(at: 1, scale: 0.9),
    ]

    /// `orbs-act 2.2s cubic-bezier(.2,.7,.2,1) infinite`
    static let act: [Keyframe] = [
        .init(at: 0, scale: 1, rotation: 0), .init(at: 0.22, scale: 1.12, rotation: 120),
        .init(at: 0.34, scale: 1, rotation: 120), .init(at: 0.56, scale: 1.12, rotation: 240),
        .init(at: 0.68, scale: 1, rotation: 240), .init(at: 0.9, scale: 1.12, rotation: 360),
        .init(at: 1, scale: 1, rotation: 360),
    ]

    static let easeInOut = CubicBezier(0.42, 0, 0.58, 1)
    static let actEase = CubicBezier(0.2, 0.7, 0.2, 1)

    static func transform(_ state: OrbsAppState, at t: Double) -> Transform {
        switch state {
        case .listening: sample(listen, progress: cycle(t, 2.6), ease: easeInOut)
        case .thinking: Transform(scale: 1, rotation: cycle(t, 4.5) * 360)
        case .acting: sample(act, progress: cycle(t, 2.2), ease: actEase)
        case .idle, .confirmation, .done, .error: rest
        }
    }

    private static func cycle(_ t: Double, _ duration: Double) -> Double {
        let p = (t / duration).truncatingRemainder(dividingBy: 1)
        return p < 0 ? p + 1 : p
    }

    /// CSS applies the animation's timing function to each keyframe segment.
    private static func sample(_ frames: [Keyframe], progress p: Double, ease: CubicBezier) -> Transform {
        guard let i = frames.lastIndex(where: { $0.at <= p }), i + 1 < frames.count else { return rest }
        let a = frames[i], b = frames[i + 1]
        let e = ease.y(atX: (p - a.at) / (b.at - a.at))
        return Transform(scale: a.scale + (b.scale - a.scale) * e, rotation: a.rotation + (b.rotation - a.rotation) * e)
    }
}

/// A CSS `cubic-bezier(x1, y1, x2, y2)` timing function.
struct CubicBezier {
    let x1, y1, x2, y2: Double

    init(_ x1: Double, _ y1: Double, _ x2: Double, _ y2: Double) {
        (self.x1, self.y1, self.x2, self.y2) = (x1, y1, x2, y2)
    }

    func y(atX x: Double) -> Double {
        if x <= 0 { return 0 }
        if x >= 1 { return 1 }
        // Solve x(s) = x by bisection; x(s) is monotonic for 0 <= x1, x2 <= 1.
        var lo = 0.0, hi = 1.0, s = x
        for _ in 0..<30 {
            let xs = Self.bezier(s, x1, x2)
            if abs(xs - x) < 1e-7 { break }
            if xs < x { lo = s } else { hi = s }
            s = (lo + hi) / 2
        }
        return Self.bezier(s, y1, y2)
    }

    private static func bezier(_ s: Double, _ p1: Double, _ p2: Double) -> Double {
        let u = 1 - s
        return 3 * u * u * s * p1 + 3 * u * s * s * p2 + s * s * s
    }
}

