struct FrozenOrb: View {
    var state: OrbsAppState; var size: CGFloat; var dark: Bool; var t: Double?
    var body: some View {
        let tuning: CGFloat = size < 36 ? 20 : 64
        let p = RingPreset.resolve(tuning: Int(tuning), dotSize: state.preset.dotSize)
        let time = t.map { $0 * p.speed * state.preset.speed } ?? 0.6
        Canvas { context, _ in
            context.scaleBy(x: size / tuning, y: size / tuning)
            for dot in RingPreset.frame(size: Double(tuning), t: time, opts: p.opts) {
                let w = min(1, max(0, dot.white))
                let g = ((dark ? 1 - w : w) * 255).rounded() / 255
                context.fill(Path(ellipseIn: CGRect(x: dot.x - dot.r, y: dot.y - dot.r, width: dot.r * 2, height: dot.r * 2)), with: .color(Color(white: g, opacity: dot.a)))
            }
        }.frame(width: size, height: size)
    }
